CREATE TABLE game_versions(id BINARY(16) PRIMARY KEY,game_id BINARY(16) NOT NULL,semantic_version VARCHAR(64) NOT NULL,status VARCHAR(30) NOT NULL,changelog TEXT NOT NULL,compatibility_json TEXT NOT NULL,supported_platforms_json TEXT NOT NULL,minimum_client_version VARCHAR(64),created_at TIMESTAMP(6) NOT NULL,revision BIGINT NOT NULL,UNIQUE(game_id,semantic_version),INDEX idx_version_game(game_id));